            FROM iptoprt o3
            WHERE o3.an = periodized.an
              AND REPLACE(UPPER(TRIM(o3.icd9)), '.', '') IN ('4513', '4514', '4515', '4516')
              AND o3.opdate >= periodized.regdate + INTERVAL '2 days'
