        WHERE fv.hn = opd_periodized.hn
          AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
          AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
          AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM ovst rv
        JOIN opdscreen rs ON rs.vn = rv.vn
        WHERE rv.hn = opd_periodized.hn
          AND rv.vstdate > opd_periodized.event_date
          AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
          AND rs.smoking_type_id IN (2, 3)
      )
    )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
      EXISTS (
        SELECT 1
        FROM ovstdiag sd
        WHERE sd.vn = opd_periodized.vn
          AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
      )
      OR EXISTS (
          SELECT 1
          FROM iptdiag idg
          WHERE idg.an = opd_periodized.an
            AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
        )
      OR EXISTS (
        SELECT 1
        FROM opdscreen scr
        WHERE scr.vn = opd_periodized.vn
          AND (
            scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
            OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
            OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
            OR scr.advice7_note ILIKE '%smoke%'
            OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
          )
      )
      OR EXISTS (
        SELECT 1
        FROM opitemrece oi
        JOIN drugitems di ON di.icode = oi.icode
        WHERE oi.vn = opd_periodized.vn
          AND (
            di.name ILIKE '%bupropion%'
            OR di.name ILIKE '%varenicline%'
            OR di.name ILIKE '%nicotine%'
          )
      )
    )), 0), 2) AS value
      FROM opd_periodized
      WHERE opd_periodized.age_y >= 15 AND (
      LEFT(pdx, 3) = 'F17'
      OR pdx = 'Z720'
      OR EXISTS (
        SELECT 1
        FROM ovstdiag sd
        WHERE sd.vn = opd_periodized.vn
          AND (
            LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
            OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
          )
      )
      OR EXISTS (
          SELECT 1
          FROM iptdiag idg
          WHERE idg.an = opd_periodized.an
            AND (
              LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) = 'F17'
              OR REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z720'
            )
        )
    ) AND (
      EXISTS (
        SELECT 1
        FROM opdscreen pg
        WHERE pg.vn = opd_periodized.vn
          AND pg.pregnancy = 'Y'
      )
      OR EXISTS (
        SELECT 1
        FROM opdscreen_pregnancy pg2
        WHERE pg2.vn = opd_periodized.vn
      )
      OR EXISTS (
          SELECT 1
          FROM ipt_pregnancy ipg
          WHERE ipg.an = opd_periodized.an
        )
      OR EXISTS (
        SELECT 1
        FROM clinicmember cm
        WHERE cm.hn = opd_periodized.hn
          AND cm.with_pregnancy = 'Y'
      )
    )
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0101' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
        1 AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.voluntary_resign_cnt) / NULLIF(12, 0) AS numerator,
        (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
        ROUND((SUM(hr.voluntary_resign_cnt) / NULLIF(12, 0)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_resign rr
            LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
            WHERE rr.emp_id = e.emp_id
              AND rr.emp_resign_date >= months.work_month
              AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
              AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE TRUE
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0102' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
        1 AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.work_injury_event_cnt) AS numerator,
        (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
        ROUND((SUM(hr.work_injury_event_cnt)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE TRUE
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0103' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
        1 AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.work_illness_event_cnt) AS numerator,
        (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
        ROUND((SUM(hr.work_illness_event_cnt)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE TRUE
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0104' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.voluntary_resign_cnt) AS numerator,
        COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
        ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_resign rr
            LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
            WHERE rr.emp_id = e.emp_id
              AND rr.emp_resign_date >= months.work_month
              AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
              AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
          ((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AS is_physician
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_physician
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0105' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.voluntary_resign_cnt) AS numerator,
        COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
        ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_resign rr
            LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
            WHERE rr.emp_id = e.emp_id
              AND rr.emp_resign_date >= months.work_month
              AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
              AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
          ((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AS is_nurse
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_nurse
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0106' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.voluntary_resign_cnt) AS numerator,
        COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
        ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_resign rr
            LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
            WHERE rr.emp_id = e.emp_id
              AND rr.emp_resign_date >= months.work_month
              AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
              AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
          (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%'])))) AS is_allied_health
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_allied_health
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0107' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.voluntary_resign_cnt) AS numerator,
        COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
        ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_resign rr
            LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
            WHERE rr.emp_id = e.emp_id
              AND rr.emp_resign_date >= months.work_month
              AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
              AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
          ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
          (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_back_office
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_back_office
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0301' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE TRUE
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0302' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.injury_lost_days) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.injury_lost_days)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COALESCE(SUM(es.emp_work_sick_countday), 0)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS injury_lost_days,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_direct_contact
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_direct_contact
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0303' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.injury_lost_days) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.injury_lost_days)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COALESCE(SUM(es.emp_work_sick_countday), 0)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS injury_lost_days,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_back_office
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_back_office
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0306' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_direct_contact
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_direct_contact
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SH0307' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_back_office
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE hr.is_back_office
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SL0101' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(brd.request_qty) AS numerator,
        SUM(brd.response_qty) AS denominator,
        ROUND(SUM(brd.request_qty) * 1 / NULLIF(SUM(brd.response_qty), 0), 2) AS value
      FROM (
      SELECT
        br.blood_request_id,
        br.vn,
        br.hn,
        br.request_date,
        DATE_TRUNC('month', br.request_date)::date AS period_start,
        EXTRACT(MONTH FROM br.request_date)::integer AS calendar_month
      FROM blood_request br
      WHERE br.request_date >= (SELECT fy_start FROM thip_params)
        AND br.request_date < (SELECT fy_end FROM thip_params)
    ) blood_requests
      JOIN blood_request_detail brd ON brd.blood_request_id = blood_requests.blood_request_id
      WHERE EXISTS (
      SELECT 1
      FROM operation_list ol
      WHERE ol.vn = blood_requests.vn
         OR (
              ol.hn = blood_requests.hn
              AND ol.operation_date >= blood_requests.request_date - INTERVAL '7 days'
              AND ol.operation_date <= blood_requests.request_date + INTERVAL '7 days'
            )
    )
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SM0102' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 1 ELSE 7 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 1 ELSE 7 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        COUNT(*) FILTER (WHERE EXISTS (
        SELECT 1
        FROM opitemrece oi
        JOIN drugitems di ON di.icode = oi.icode
        WHERE oi.vn = opd_periodized.vn
          AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
      )) AS numerator,
        COUNT(*) AS denominator,
        ROUND((COUNT(*) FILTER (WHERE EXISTS (
        SELECT 1
        FROM opitemrece oi
        JOIN drugitems di ON di.icode = oi.icode
        WHERE oi.vn = opd_periodized.vn
          AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
      )) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
      FROM opd_periodized
      WHERE (
      LEFT(pdx, 3) = 'J00'
      OR pdx IN ('B053', 'H650', 'H651', 'H659', 'H660', 'H664', 'H669', 'H670', 'H671', 'H678', 'H720', 'H722', 'H728', 'H729', 'J010', 'J014', 'J018', 'J019', 'J020', 'J029', 'J030', 'J038', 'J039', 'J040', 'J042', 'J050', 'J051', 'J060', 'J068', 'J069', 'J101', 'J111', 'J200', 'J209', 'J210', 'J218', 'J219')
      OR EXISTS (
        SELECT 1
        FROM ovstdiag sd
        WHERE sd.vn = opd_periodized.vn
          AND (
            LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'J00'
            OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('B053', 'H650', 'H651', 'H659', 'H660', 'H664', 'H669', 'H670', 'H671', 'H678', 'H720', 'H722', 'H728', 'H729', 'J010', 'J014', 'J018', 'J019', 'J020', 'J029', 'J030', 'J038', 'J039', 'J040', 'J042', 'J050', 'J051', 'J060', 'J068', 'J069', 'J101', 'J111', 'J200', 'J209', 'J210', 'J218', 'J219')
          )
      )
    )
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SM0103' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 1 ELSE 7 END)) AS period_start,
        CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 1 ELSE 7 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        COUNT(*) FILTER (WHERE EXISTS (
        SELECT 1
        FROM opitemrece oi
        JOIN drugitems di ON di.icode = oi.icode
        WHERE oi.vn = opd_periodized.vn
          AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
      )) AS numerator,
        COUNT(*) AS denominator,
        ROUND((COUNT(*) FILTER (WHERE EXISTS (
        SELECT 1
        FROM opitemrece oi
        JOIN drugitems di ON di.icode = oi.icode
        WHERE oi.vn = opd_periodized.vn
          AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
      )) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
      FROM opd_periodized
      WHERE (
      LEFT(pdx, 3) = 'A09'
      OR pdx IN ('A000', 'A001', 'A009', 'A020', 'A030', 'A033', 'A038', 'A039', 'A040', 'A049', 'A050', 'A053', 'A054', 'A059', 'A080', 'A085', 'K521', 'K528', 'K529')
      OR EXISTS (
        SELECT 1
        FROM ovstdiag sd
        WHERE sd.vn = opd_periodized.vn
          AND (
            LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'A09'
            OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A000', 'A001', 'A009', 'A020', 'A030', 'A033', 'A038', 'A039', 'A040', 'A049', 'A050', 'A053', 'A054', 'A059', 'A080', 'A085', 'K521', 'K528', 'K529')
          )
      )
    )
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SM0201' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        MAX((
        SELECT SUM(bal.left_value)
        FROM (
          SELECT DISTINCT ON (st.item_id) (st.left_qty * st.price) AS left_value
          FROM stock_trancation st
          WHERE st.transaction_date >= opd_periodized.period_start
            AND st.transaction_date < opd_periodized.period_start + INTERVAL '1 month'
          ORDER BY st.item_id, st.transaction_date DESC, st.stock_trancation_id DESC
        ) bal
      )) AS numerator,
        MAX((
        SELECT SUM(st2.out_qty * st2.price)
        FROM stock_trancation st2
        WHERE st2.transaction_date >= opd_periodized.period_start
          AND st2.transaction_date < opd_periodized.period_start + INTERVAL '1 month'
          AND COALESCE(st2.out_qty, 0) > 0
      )) AS denominator,
        ROUND((MAX((
        SELECT SUM(bal.left_value)
        FROM (
          SELECT DISTINCT ON (st.item_id) (st.left_qty * st.price) AS left_value
          FROM stock_trancation st
          WHERE st.transaction_date >= opd_periodized.period_start
            AND st.transaction_date < opd_periodized.period_start + INTERVAL '1 month'
          ORDER BY st.item_id, st.transaction_date DESC, st.stock_trancation_id DESC
        ) bal
      )) * 1.0) / NULLIF(MAX((
        SELECT SUM(st2.out_qty * st2.price)
        FROM stock_trancation st2
        WHERE st2.transaction_date >= opd_periodized.period_start
          AND st2.transaction_date < opd_periodized.period_start + INTERVAL '1 month'
          AND COALESCE(st2.out_qty, 0) > 0
      )), 0), 2) AS value
      FROM opd_periodized
      WHERE opd_periodized.event_date IS NOT NULL
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SS0102' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        COUNT(*) FILTER (
        WHERE sterile_batches.supply_sterile_complete = 'Y'
          AND sterile_batches.supply_sterile_confirm = 'Y'
          AND NOT EXISTS (
            SELECT 1
            FROM supply_sterile_list sl
            WHERE sl.supply_sterile_id = sterile_batches.supply_sterile_id
              AND COALESCE(sl.supply_sterile_list_complete, 'N') <> 'Y'
          )
      ) AS numerator,
        COUNT(*) AS denominator,
        ROUND(COUNT(*) FILTER (
        WHERE sterile_batches.supply_sterile_complete = 'Y'
          AND sterile_batches.supply_sterile_confirm = 'Y'
          AND NOT EXISTS (
            SELECT 1
            FROM supply_sterile_list sl
            WHERE sl.supply_sterile_id = sterile_batches.supply_sterile_id
              AND COALESCE(sl.supply_sterile_list_complete, 'N') <> 'Y'
          )
      ) * 100 / NULLIF(COUNT(*), 0), 2) AS value
      FROM (
      SELECT
        st.supply_sterile_id,
        st.supply_sterile_date,
        st.supply_sterile_confirm,
        st.supply_sterile_complete,
        DATE_TRUNC('month', st.supply_sterile_date)::date AS period_start,
        EXTRACT(MONTH FROM st.supply_sterile_date)::integer AS calendar_month
      FROM supply_sterile st
      WHERE st.supply_sterile_date >= (SELECT fy_start FROM thip_params)
        AND st.supply_sterile_date < (SELECT fy_end FROM thip_params)
    ) sterile_batches
      WHERE TRUE
      GROUP BY 2, 3, 4

      UNION ALL

      SELECT
        'SS0103' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        COUNT(*) FILTER (
        WHERE sterile_receipts.supply_sterile_receive_status = 'Y'
          AND EXISTS (
            SELECT 1
            FROM supply_sterile st
            WHERE st.supply_sterile_id = sterile_receipts.supply_sterile_id
              AND st.supply_sterile_confirm = 'Y'
          )
      ) AS numerator,
        COUNT(*) AS denominator,
        ROUND(COUNT(*) FILTER (
        WHERE sterile_receipts.supply_sterile_receive_status = 'Y'
          AND EXISTS (
            SELECT 1
            FROM supply_sterile st
            WHERE st.supply_sterile_id = sterile_receipts.supply_sterile_id
              AND st.supply_sterile_confirm = 'Y'
          )
      ) * 100 / NULLIF(COUNT(*), 0), 2) AS value
      FROM (
      SELECT
        sr.supply_sterile_receive_id,
        sr.supply_sterile_id,
        sr.supply_sterile_receive_date,
        sr.supply_sterile_receive_status,
        DATE_TRUNC('month', sr.supply_sterile_receive_date)::date AS period_start,
        EXTRACT(MONTH FROM sr.supply_sterile_receive_date)::integer AS calendar_month
      FROM supply_sterile_receive sr
      WHERE sr.supply_sterile_receive_date >= (SELECT fy_start FROM thip_params)
        AND sr.supply_sterile_receive_date < (SELECT fy_end FROM thip_params)
    ) sterile_receipts
      WHERE TRUE
      GROUP BY 2, 3, 4
      ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
